string[] rows = ["att,pass,82", "att,fail,41", "hdr,ignore,0"];

// Query syntax — from comes first so row is in scope
IEnumerable<string> query =
    from row in rows
    let parts = row.Split(',')
    where parts[0] == "att" && int.Parse(parts[2]) >= 50
    select parts[1];

// Method syntax — same logic as a chain
IEnumerable<string> method = rows
    .Select(row => row.Split(','))
    .Where(parts => parts[0] == "att" && int.Parse(parts[2]) >= 50)
    .Select(parts => parts[1]);

var passingCount = (from row in rows
                    where row.Contains("pass", StringComparison.Ordinal)
                    select row).Count();

// Count has no query-syntax keyword — append it as a method.
// Count is immediate: the where/select plan runs once inside Count.

var attempts = new[] { new { Id = 1, Answers = new[] { "A", "B" } } };

// Query syntax: two from clauses
var flatQuery = from att in attempts
                from ans in att.Answers
                select ans;

// Compiler rewrites to SelectMany
var flatMethod = attempts.SelectMany(att => att.Answers);
